--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "NET"."TRG_CELL_BI"
  BEFORE INSERT ON "NET"."CELL"
  FOR EACH ROW
BEGIN
  IF :NEW.CELL_ID IS NULL THEN
    :NEW.CELL_ID := "NET"."SEQ_CELL".NEXTVAL;
  END IF;
