--  DDL for Trigger TRG_CDR_SOURCE_BI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "CDR"."TRG_CDR_SOURCE_BI"
  BEFORE INSERT ON "CDR"."CDR_SOURCE"
  FOR EACH ROW
BEGIN
  IF :NEW.CDR_SOURCE_ID IS NULL THEN
    :NEW.CDR_SOURCE_ID := "CDR"."SEQ_CDR_SOURCE".NEXTVAL;
  END IF;
  -- not: ; ve / karakterleri burada ifadeyi bitirmemeli
  :NEW.CREATED_BY := NVL(SYS_CONTEXT('USERENV','CLIENT_IDENTIFIER'), USER);
END;
/
ALTER TRIGGER "CDR"."TRG_CDR_SOURCE_BI" ENABLE;
