--------------------------------------------------------
--  DDL for Trigger TRG_ADDRESS_HIST_BI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "CRM"."TRG_ADDRESS_HIST_BI"
  BEFORE INSERT ON "CRM"."ADDRESS_HIST"
  FOR EACH ROW
BEGIN
  IF :NEW.ADDRESS_HIST_ID IS NULL THEN
    :NEW.ADDRESS_HIST_ID := "CRM"."SEQ_ADDRESS_HIST".NEXTVAL;
  END IF;
  -- not: ; ve / karakterleri burada ifadeyi bitirmemeli
  :NEW.CREATED_BY := NVL(SYS_CONTEXT('USERENV','CLIENT_IDENTIFIER'), USER);
END;
/
ALTER TRIGGER "CRM"."TRG_ADDRESS_HIST_BI" ENABLE;
