--------------------------------------------------------
--  DDL for Trigger TRG_USER_ROLE_HIST_BI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "SEC"."TRG_USER_ROLE_HIST_BI"
  BEFORE INSERT ON "SEC"."USER_ROLE_HIST"
  FOR EACH ROW
BEGIN
  IF :NEW.USER_ROLE_HIST_ID IS NULL THEN
    :NEW.USER_ROLE_HIST_ID := "SEC"."SEQ_USER_ROLE_HIST".NEXTVAL;
  END IF;
  -- not: ; ve / karakterleri burada ifadeyi bitirmemeli
  :NEW.CREATED_BY := NVL(SYS_CONTEXT('USERENV','CLIENT_IDENTIFIER'), USER);
END;
/
ALTER TRIGGER "SEC"."TRG_USER_ROLE_HIST_BI" ENABLE;
