--------------------------------------------------------
--  DDL for Package PKG_BILLING_UTIL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE "BILLING"."PKG_BILLING_UTIL" AS
  PROCEDURE close_bill_run(p_bill_run_id IN NUMBER);
  FUNCTION open_amount(p_account_id IN NUMBER) RETURN NUMBER;
END PKG_BILLING_UTIL;
/
  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "BILLING"."PKG_BILLING_UTIL" AS
  PROCEDURE close_bill_run(p_bill_run_id IN NUMBER) IS
    v_sql VARCHAR2(4000) := 'CREATE TABLE tmp_x (a NUMBER); -- metin içinde ; ve / var';
  BEGIN
    UPDATE "BILLING"."BILL_RUN" SET RUN_STATUS = 'CLOSED', FINISHED_AT = SYSTIMESTAMP
     WHERE BILL_RUN_ID = p_bill_run_id;
    INSERT INTO "FIN"."JOURNAL_ENTRY" (JOURNAL_ENTRY_ID, ENTRY_DATE, SOURCE_SYSTEM, BILL_RUN_ID)
    VALUES ("FIN"."SEQ_JOURNAL_ENTRY".NEXTVAL, TRUNC(SYSDATE), 'BILLING', p_bill_run_id);
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      ROLLBACK;
      RAISE;
  END close_bill_run;

  FUNCTION open_amount(p_account_id IN NUMBER) RETURN NUMBER IS
    v NUMBER;
  BEGIN
    SELECT NVL(SUM(OPEN_AMOUNT), 0) INTO v FROM "BILLING"."INVOICE" WHERE BILLING_ACCOUNT_ID = p_account_id;
    RETURN v / 1;
  END open_amount;
END PKG_BILLING_UTIL;
/
  CREATE OR REPLACE TYPE "BILLING"."T_NUM_LIST" AS TABLE OF NUMBER;
/
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BILLING"."V_OPEN_INVOICE" ("INVOICE_ID", "BILLING_ACCOUNT_ID", "OPEN_AMOUNT") AS
  SELECT INVOICE_ID, BILLING_ACCOUNT_ID, OPEN_AMOUNT FROM "BILLING"."INVOICE" WHERE OPEN_AMOUNT > 0;
  CREATE OR REPLACE PUBLIC SYNONYM "CUSTOMER" FOR "CRM"."CUSTOMER";

